213			cout << "    （未提取到任何文法规则，请检查文法文件的书写格式）" << endl << endl;
214			return;
215		}
216		for (unsigned int i = 0; i < rules.size(); i++) {
217			cout << "    " << rules[i] << endl;
218		}
219		cout << endl;
220	}
