77		expect_eq(to_s(findFirst("Ab", g.rules)), "First(Ab)={a,e}", "G3 First(Ab)");
78		expect_eq(to_s(findFirst("@", g.rules)), "First(@)={@}", "G3 First(@)");
79		expect_eq(to_s(findFirst("aM", g.rules)), "First(aM)={a}", "G3 First(aM)");
80		expect_eq(to_s(findFirst("e", g.rules)), "First(e)={e}", "G3 First(e)");
