		out << setw(12) << table.col[j];
	}
	out << endl;
	//表中每一行以非终结符开头，空单元格表示分析到此处即出错
	for (unsigned int i = 0; i < table.row.size(); i++) {
		out << setw(8) << table.row[i];
		for (unsigned int j = 0; j < table.col.size(); j++) {
			ostringstream cell;
			unsigned int at = i * table.col.size() + j;
			if (at < table.rules.size() && !table.rules[at].right.empty()) {
				//借助字符串流把整条产生式当作一个整体输出，列宽才不会被打乱
				cell << table.rules[at];
			}
			out << setw(12) << cell.str();
		}
		out << endl;
	}
	out << endl;
	return out;
}
